{"sdk_http_response":{"headers":{"x-gemini-service-tier":"standard","content-type":"application/json; charset=UTF-8","vary":"Origin, X-Origin, Referer","content-encoding":"gzip","date":"Tue, 18 Aug 2026 07:11:55 GMT","server":"scaffolding on HTTPServer2","x-xss-protection":"0","x-frame-options":"SAMEORIGIN","x-content-type-options":"nosniff","server-timing":"gfet4t7; dur=16561","alt-svc":"h3=":443"; ma=2592000,h3-29=":443"; ma=2592000","transfer-encoding":"chunked"},"body":null},"candidates":[{"content":{"parts":[{"media_resolution":null,"code_execution_result":null,"executable_code":null,"file_data":null,"function_call":null,"function_response":null,"inline_data":null,"text":"{
